    for (id, original, expected) in cases {
        let bytes = Data(original.utf8)
        let result = ScopeResolution.resolve(original)
        try check(result.scope == expected, "scope: \(id)")
        try check(Data(original.utf8) == bytes, "original source unchanged: \(id)")
        if id == "actual_D1" {
            try check(result.prohibitions.contains("do not modify test_public_spans.py, create extra files, access the network or inspect anything outside this workspace"),
                "entire original negative action list is retained")
        }
        if id == "compound_repeat_negation" {
            try check(result.prohibitions.contains("never edit paid.csv, and do not create other files or access the network"),
                "repeated negative action prefix retains whole clause")
        }
    }
    let creationFence = "Modify only report.csv; do not change tests.csv, create files, use network services or inspect outside this workspace."
    let creationResult = ScopeResolution.resolve(creationFence)
    try check(creationResult.prohibitions.contains("do not change tests.csv, create files, use network services or inspect outside this workspace"), "exact whole no-new-file/network/outside prohibition survives")
    try check(ScopeResolution.routingObjective(creationFence, scope: creationResult.scope).contains(creationFence), "routing handoff retains original source rather than normalized analysis view")
    let koreanFence = "result.py만 고쳐, settings.yaml은 수정하지 마."
    let koreanResult = ScopeResolution.resolve(koreanFence)
    try check(koreanResult.prohibitions.contains("settings.yaml은 수정하지 마"), "Korean preservation clause survives verbatim in normalized prohibition view")
    try check(ScopeResolution.routingObjective(koreanFence, scope: koreanResult.scope).contains(koreanFence), "worker gets original Korean request, not canonical analysis text")
    try check(ScopeResolution.resolve(koreanFence.decomposedStringWithCanonicalMapping) == koreanResult, "NFC/NFD scope and prohibition equality")
    try check(ScopeResolution.resolve("승인받은 뒤에만 진행해. " + koreanFence).prohibitions.contains("승인받은 뒤에만 진행해"),
              "whole unresolved enclosing authority clause retained, not erased by a bounded filename match")

    // Data immutability constrains implementation semantics; it is not a
    // blanket filesystem ban beside an independently authorized file edit.
    let inputValueWrites = [
        "Modify labels.py. Do not change the input list.",
        "Repair records.csv. Do not modify input arrays.",
        "Fix config.yaml. Never alter the input dictionary.",
        "labels.py 파일 하나만 수정하세요. 입력 리스트는 변경하지 마세요.",
        "result.py만 고쳐. 입력 배열은 수정하지 마세요.",
        "현재 폴더의 report.py 파일만 편집하십시오. 입력 객체를 변경하지 마십시오.",
        "입력 인수는 변경하지 마세요. result.py만 수정해줘.",
    ]
    for request in inputValueWrites {
        let result = ScopeResolution.resolve(request)
        try check(result.scope == .workspaceWrite, "input VALUE fence is not a global file ban")
        try check(result.prohibitions.contains(where: { $0.contains("input") || $0.contains("입력") }), "full input VALUE constraint retained")
        try check(ScopeResolution.routingObjective(request, scope: result.scope).contains(request), "original handoff unchanged")
        try check(ScopeResolution.resolve(request.decomposedStringWithCanonicalMapping) == result, "input VALUE fence normalization stable")
    }
    let noValueAuthority = [
